corrected_code:
def get_user_kpi_dashboards(request):
    dashboards = get_objects_for_user(
        request.user,
        'analytics.view_kpidashboard',
        klass=KpiDashboard.objects.filter(organization=request.user.organization),
        accept_global_perms=False
    )
    return JsonResponse({'dashboards': [{'id': d.id, 'title': d.title, 'org': d.organization_id} for d in dashboards]})
